<?php require_once __DIR__."/../config/auth.php";require_role(["admin"]);$pdo=db();if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf($_POST["csrf"]??"");$pdo->prepare("INSERT INTO suppliers(name,phone,address,tax_no) VALUES(?,?,?,?)")->execute([$_POST["name"],$_POST["phone"],$_POST["address"],$_POST["tax_no"]]);$_SESSION["flash"]=["type"=>"ok","msg"=>"Supplier added."];redirect("suppliers.php");}$rows=$pdo->query("SELECT * FROM suppliers ORDER BY id DESC")->fetchAll();include __DIR__."/partials/header.php";?><header><h1><?=t("الموردين","Suppliers")?></h1></header><div class="card"><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="name" placeholder="Supplier name" required><input name="phone" placeholder="Phone"><input name="address" placeholder="Address"><input name="tax_no" placeholder="Tax no"><button class="btn primary">Add</button></form></div><div class="card"><table><tr><th>Name</th><th>Phone</th><th>Balance</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r["name"])?></td><td><?=e($r["phone"])?></td><td><?=number_format($r["balance"],2)?></td></tr><?php endforeach;?></table></div><?php include __DIR__."/partials/footer.php";?>